import React, { useState, useEffect, useRef } from 'react';

interface KnobProps {
  label: string;
  value: number; // 0 to 1 usually, or specific range
  min?: number;
  max?: number;
  onChange: (val: number) => void;
  color?: string;
}

const Knob: React.FC<KnobProps> = ({ label, value, min = 0, max = 1, onChange, color = '#FFD700' }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef<number>(0);
  const startVal = useRef<number>(0);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    startY.current = e.clientY;
    startVal.current = value;
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging) return;
      const delta = startY.current - e.clientY;
      const range = max - min;
      const sensitivity = 0.005 * range; // Value change per pixel

      let newValue = startVal.current + delta * sensitivity;
      newValue = Math.max(min, Math.min(max, newValue));

      onChange(newValue);
    };

    const handleMouseUp = () => {
      setIsDragging(false);
    };

    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, max, min, onChange]);

  // Calculate rotation: 0 value = -145deg, Max value = 145deg
  const percentage = (value - min) / (max - min);
  const rotation = -145 + (percentage * 290);

  return (
    <div className="flex flex-col items-center select-none group">
      <div 
        className="relative w-12 h-12 rounded-full border-2 border-[#333] bg-[#1E1E1E] cursor-ns-resize hover:border-[#555] transition-colors"
        onMouseDown={handleMouseDown}
      >
        <div 
          className="absolute w-full h-full rounded-full"
          style={{ transform: `rotate(${rotation}deg)` }}
        >
            <div 
                className="absolute top-1 left-1/2 -translate-x-1/2 w-1.5 h-3 rounded-full shadow-[0_0_5px_rgba(0,0,0,0.5)]"
                style={{ backgroundColor: color }}
            />
        </div>
      </div>
      <span className="text-[10px] mt-2 font-mono text-[#A0A0A0] group-hover:text-[#E0E0E0] uppercase tracking-wider">
        {label}
      </span>
      <span className="text-[9px] text-[#555] font-mono">
        {value.toFixed(2)}
      </span>
    </div>
  );
};

export default Knob;

import React, { useState } from 'react';
import { Upload, Music, Layers, CheckCircle } from 'lucide-react';
import { THEME } from '../constants';

const StemSplitter: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [processing, setProcessing] = useState(false);
  const [progress, setProgress] = useState(0);
  const [stems, setStems] = useState<string[]>([]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
      setStems([]);
      setProgress(0);
    }
  };

  const processStems = () => {
    if (!file) return;
    setProcessing(true);
    // Simulate processing
    let p = 0;
    const interval = setInterval(() => {
      p += 2;
      setProgress(p);
      if (p >= 100) {
        clearInterval(interval);
        setProcessing(false);
        setStems(['Vocals', 'Drums', 'Bass', 'Other']);
      }
    }, 50);
  };

  return (
    <div className="h-full p-8 flex flex-col space-y-8 animate-fade-in">
      <div className="space-y-2">
        <h2 className="text-3xl font-bold text-white tracking-tight flex items-center gap-3">
          <Layers className="text-[#FFD700]" />
          STEM SPLITTER
        </h2>
        <p className="text-[#A0A0A0] max-w-2xl">
          Isolate vocals, drums, bass, and instruments using advanced Demucs (Hybrid Transformer) models. 
          Optimized for 6GB VRAM with automatic lazy-unloading.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 h-full">
        {/* Dropzone Area */}
        <div className="bg-[#1E1E1E] border border-[#333] rounded-xl p-8 flex flex-col items-center justify-center text-center hover:border-[#FFD700] transition-colors group relative overflow-hidden">
          <input 
            type="file" 
            accept="audio/*"
            onChange={handleFileUpload}
            className="absolute inset-0 opacity-0 cursor-pointer z-10"
          />
          <div className="bg-[#121212] p-6 rounded-full mb-6 group-hover:scale-110 transition-transform duration-300">
             <Upload size={48} color={file ? THEME.colors.gold : '#333'} />
          </div>
          <h3 className="text-xl font-medium text-white mb-2">
            {file ? file.name : "Drop Audio File Here"}
          </h3>
          <p className="text-sm text-[#666]">
            Supports MP3, WAV, FLAC (Max 100MB)
          </p>
        </div>

        {/* Status / Output Area */}
        <div className="bg-[#1E1E1E] border border-[#333] rounded-xl p-8 flex flex-col">
          <h3 className="text-[#FFD700] font-mono text-sm uppercase tracking-wider mb-6 border-b border-[#333] pb-2">
            Processing Queue
          </h3>

          {!file && (
            <div className="flex-1 flex items-center justify-center text-[#333] font-mono text-sm italic">
              Waiting for input...
            </div>
          )}

          {file && !processing && stems.length === 0 && (
             <div className="flex-1 flex flex-col items-center justify-center space-y-4">
               <div className="text-white font-mono">Ready to split</div>
               <button 
                onClick={processStems}
                className="bg-[#FFD700] text-black px-8 py-3 rounded-md font-bold hover:bg-[#D4B200] transition-colors"
               >
                 INITIALIZE DEMUCS
               </button>
               <span className="text-xs text-[#666]">Model will load into VRAM on click</span>
             </div>
          )}

          {processing && (
            <div className="flex-1 flex flex-col items-center justify-center space-y-6">
               <div className="w-full space-y-2">
                  <div className="flex justify-between text-xs font-mono text-[#FFD700]">
                    <span>EXTRACTING STEMS...</span>
                    <span>{progress}%</span>
                  </div>
                  <div className="h-2 bg-[#121212] rounded-full overflow-hidden">
                    <div 
                        className="h-full bg-[#FFD700]" 
                        style={{ width: `${progress}%` }}
                    />
                  </div>
               </div>
               <div className="font-mono text-xs text-[#666] animate-pulse">
                  &gt; torch.cuda.memory_allocated(): 2.4GB
               </div>
            </div>
          )}

          {stems.length > 0 && (
            <div className="space-y-4 animate-slide-up">
              {stems.map((stem, i) => (
                <div key={i} className="flex items-center justify-between bg-[#121212] p-3 rounded border border-[#333] hover:border-[#555]">
                  <div className="flex items-center gap-3">
                    <Music size={16} className="text-[#666]" />
                    <span className="text-sm font-medium">{stem}.wav</span>
                  </div>
                  <CheckCircle size={16} className="text-[#FFD700]" />
                </div>
              ))}
              <div className="mt-4 p-3 bg-green-900/20 border border-green-900 rounded text-xs text-green-500 font-mono text-center">
                 VRAM RELEASED: CACHE CLEARED
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default StemSplitter;

