import React, { useState } from 'react';
import { Terminal, Code, Download, Cpu } from 'lucide-react';
import { generateSystemCode } from '../services/geminiService';

const SystemCore: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'hardware' | 'reqs'>('hardware');
  const [code, setCode] = useState<string>('# Click "Generate" to build this module using Gemini AI.');
  const [loading, setLoading] = useState(false);

  const handleGenerate = async () => {
    setLoading(true);
    setCode('# Querying Strangelet AI Core...');

    let promptContext = "";
    let filename = "";

    if (activeTab === 'hardware') {
      filename = "hardware.py";
      promptContext = "Manage 6GB VRAM limit. Implement Singleton pattern for ModelManager. Use lazy loading: load_model(name), unload_model(). Support CUDA and DirectML detection.";
    } else {
      filename = "requirements.txt";
      promptContext = "Include libraries for: Demucs, RVC, PyTorch (CUDA capable), Librosa, SoundFile, NumPy, and PySide6 for potential UI expansions.";
    }

    const result = await generateSystemCode(filename, promptContext);
    setCode(result);
    setLoading(false);
  };

  return (
    <div className="h-full p-6 flex flex-col gap-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-white tracking-tight flex items-center gap-3">
          <Terminal className="text-[#FFD700]" />
          SYSTEM CORE <span className="text-[#666] text-sm font-normal font-mono px-2 py-1 bg-[#222] rounded">CODE GENERATOR</span>
        </h2>
      </div>

      <div className="bg-[#1E1E1E] border border-[#333] rounded-xl flex flex-col h-full overflow-hidden">
        {/* Tabs */}
        <div className="flex border-b border-[#333]">
          <button 
            onClick={() => { setActiveTab('hardware'); setCode('# Click Generate'); }}
            className={`px-6 py-3 font-mono text-sm flex items-center gap-2 ${activeTab === 'hardware' ? 'bg-[#252525] text-[#FFD700] border-b-2 border-[#FFD700]' : 'text-[#666] hover:text-[#E0E0E0]'}`}
          >
            <Cpu size={14} /> hardware.py
          </button>
          <button 
            onClick={() => { setActiveTab('reqs'); setCode('# Click Generate'); }}
            className={`px-6 py-3 font-mono text-sm flex items-center gap-2 ${activeTab === 'reqs' ? 'bg-[#252525] text-[#FFD700] border-b-2 border-[#FFD700]' : 'text-[#666] hover:text-[#E0E0E0]'}`}
          >
            <Code size={14} /> requirements.txt
          </button>
        </div>

        {/* Toolbar */}
        <div className="p-4 bg-[#121212] flex justify-between items-center border-b border-[#333]">
          <div className="text-xs text-[#666] font-mono">
            STATUS: {loading ? 'GENERATING...' : 'READY'}
          </div>
          <button 
            onClick={handleGenerate}
            disabled={loading}
            className={`px-4 py-1.5 rounded text-xs font-bold uppercase tracking-wider flex items-center gap-2 transition-all ${loading ? 'bg-[#333] text-[#666] cursor-not-allowed' : 'bg-[#FFD700] text-black hover:bg-[#E5C100]'}`}
          >
            <Download size={14} />
            {loading ? 'Processing...' : 'Generate Code'}
          </button>
        </div>

        {/* Code View */}
        <div className="flex-1 bg-[#0A0A0A] p-6 overflow-auto font-mono text-xs text-[#A0A0A0]">
          <pre className="whitespace-pre-wrap">
            {code}
          </pre>
        </div>
      </div>
    </div>
  );
};

