import { GoogleGenAI } from "@google/genai";

let ai: GoogleGenAI | null = null;

const getAI = () => {
  if (!ai) {
    ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }
  return ai;
};

export const generateSystemCode = async (filename: string, context: string): Promise<string> => {
  const client = getAI();
  try {
    const prompt = `
      You are an expert Python engineer specializing in Audio Processing and AI pipelines.
      The user is building "Strangelet Lab", an AI music workstation.

      Context: ${context}

      Task: Generate the complete source code for the file: '${filename}'.
      Style: Professional, type-hinted Python code using PyTorch where applicable.
      Constraints: 
      - If hardware.py: Implement lazy loading, VRAM management (6GB limit), torch.cuda.empty_cache(), and support for CUDA/DirectML. Optimize for mechanical HDD I/O where possible.
      - If requirements.txt: List all necessary dependencies for Demucs, RVC, PyTorch, PySide6/PyQt (for UI if applicable, though this is a web simulation), Librosa, etc.
      - The system should be configurable to use different AI endpoints like a local LM Studio server or a cloud service like OpenRouter.

      Return ONLY the raw code/text content, no markdown formatting blocks if possible, or minimally wrapped.
    `;

    const response = await client.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || '# Error generating code.';
  } catch (error) {
    console.error("Gemini Error:", error);
    return `# Error: Unable to generate code. Ensure API Key is valid.\n# ${error}`;
  }
};

export const analyzeMix = async (description: string): Promise<string> => {
    const client = getAI();
    try {
        const response = await client.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Analyze this mixing scenario and provide spectral rebuilding advice using 'Strangelet Lab's Mastering Engineer' module philosophy (AudioSR/Matchering reference): ${description}`,
        });
        return response.text || "Analysis failed.";
    } catch (e) {
        return "Could not connect to AI Neural Net.";
    }
}

import React, { useState, useEffect, useRef } from 'react';
import { INITIAL_TRACKS } from '../constants';
import { Track } from '../types';
import ChannelStrip from './ChannelStrip';
import { Settings2, Play, Pause, Square, Repeat, Rewind } from 'lucide-react';

const TOTAL_BARS = 16;

const Mixer: React.FC = () => {
  const [tracks, setTracks] = useState<Track[]>(INITIAL_TRACKS);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const [playheadPosition, setPlayheadPosition] = useState<number>(0); // 0 to 1
  const [loopEnabled, setLoopEnabled] = useState<boolean>(true);
  const [loopRange, setLoopRange] = useState<{ start: number, end: number }>({ start: 0.25, end: 0.75 }); // 0 to 1
  const animationFrameRef = useRef<number>();

  const updateTrack = (id: string, updates: Partial<Track>) => {
    setTracks(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t));
  };

  useEffect(() => {
    const animate = () => {
      setPlayheadPosition(prev => {
        let nextPos = prev + 0.0005; // Adjust speed
        if (loopEnabled && nextPos >= loopRange.end) {
          return loopRange.start;
        }
        if (nextPos >= 1) {
          setIsPlaying(false);
          return 0;
        }
        return nextPos;
      });
      animationFrameRef.current = requestAnimationFrame(animate);
    };

    if (isPlaying) {
      animationFrameRef.current = requestAnimationFrame(animate);
    } else {
      cancelAnimationFrame(animationFrameRef.current!);
    }

    return () => cancelAnimationFrame(animationFrameRef.current!);
  }, [isPlaying, loopEnabled, loopRange]);

  const handleTransportClick = (action: 'play' | 'pause' | 'stop' | 'rewind' | 'loop') => {
    switch(action) {
      case 'play': setIsPlaying(true); break;
      case 'pause': setIsPlaying(false); break;
      case 'stop': setIsPlaying(false); setPlayheadPosition(0); break;
      case 'rewind': setPlayheadPosition(0); break;
      case 'loop': setLoopEnabled(prev => !prev); break;
    }
  };

  return (
    <div className="h-full flex flex-col p-4 md:p-6 overflow-hidden bg-[#0A0A0A]">
      <h2 className="text-xl md:text-2xl font-bold text-white tracking-tight flex items-center gap-3 mb-4">
          <Settings2 className="text-[#FFD700]" />
          MIXER CONSOLE
      </h2>

      {/* Temporal Lattice (Timeline) */}
      <div className="w-full h-24 bg-[#151515] border border-[#333] rounded-t-xl p-2 relative flex flex-col justify-center">
        <div className="w-full h-full grid grid-cols-16 relative">
          {Array.from({ length: TOTAL_BARS }).map((_, i) => (
            <div key={i} className={`h-full ${i % 4 === 0 ? 'border-l-2 border-[#555]' : 'border-l border-[#222]'}`}>
                <span className="text-[10px] text-[#444] absolute mt-1 ml-1">{i+1}</span>
            </div>
          ))}
        </div>
        {/* Loop Brackets & Playhead */}
        <div className="absolute inset-2 top-8 pointer-events-none">
          <div 
            className="absolute top-0 h-full bg-[#FFD700]/10 border-x-2 border-[#FFD700]"
            style={{ left: `${loopRange.start * 100}%`, width: `${(loopRange.end - loopRange.start) * 100}%` }}
          />
          <div 
            className="absolute top-0 h-full w-0.5 bg-red-500 shadow-[0_0_8px_rgba(255,0,0,0.8)]"
            style={{ left: `${playheadPosition * 100}%` }}
          />
        </div>
      </div>

      {/* Channel Strips Area */}
      <div className="flex-1 bg-[#1E1E1E] border-x border-b border-[#333] p-4 flex justify-around gap-4 overflow-x-auto">
        {tracks.map(track => (
          <ChannelStrip key={track.id} track={track} updateTrack={updateTrack} />
        ))}
      </div>

      {/* Transport Bar */}
      <div className="h-20 bg-[#121212] border border-[#333] rounded-b-xl mt-2 flex items-center justify-center gap-4">
        <button onClick={() => handleTransportClick('rewind')} className="p-3 text-[#A0A0A0] hover:text-[#FFD700]"><Rewind /></button>
        <button onClick={() => handleTransportClick('stop')} className="p-3 text-[#A0A0A0] hover:text-[#FFD700]"><Square /></button>
        <button onClick={() => isPlaying ? handleTransportClick('pause') : handleTransportClick('play')} className="p-4 bg-[#FFD700] text-black rounded-full shadow-[0_0_15px_rgba(255,215,0,0.4)] hover:bg-white">
          {isPlaying ? <Pause /> : <Play />}
        </button>
        <button onClick={() => handleTransportClick('loop')} className={`p-3 rounded ${loopEnabled ? 'text-[#FFD700] bg-[#FFD700]/10' : 'text-[#A0A0A0]'} hover:text-[#FFD700]`}>
          <Repeat />
        </button>
      </div>
    </div>
  );
};

export default Mixer;

import React, { useState, useRef, useEffect } from 'react';
