const Fader: React.FC<{ value: number, onChange: (val: number) => void }> = ({ value, onChange }) => {
    const faderRef = useRef<HTMLDivElement>(null);
    const [isDragging, setIsDragging] = useState(false);

    const handleMouseDown = (e: React.MouseEvent) => {
        setIsDragging(true);
    };

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (!isDragging || !faderRef.current) return;
            const rect = faderRef.current.getBoundingClientRect();
            const trackHeight = rect.height;
            const clientY = e.clientY - rect.top;

            let newValue = 1 - (clientY / trackHeight);
            newValue = Math.max(0, Math.min(1, newValue));
            onChange(newValue);
        };

        const handleMouseUp = () => {
            setIsDragging(false);
        };

        if (isDragging) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging, onChange]);

    // Convert linear 0-1 value to logarithmic dB scale for display
    const toDB = (linear: number) => {
        if (linear === 0) return -Infinity;
        return 20 * Math.log10(linear);
    }
    const dbValue = toDB(value);
    const displayDb = isFinite(dbValue) ? dbValue.toFixed(1) : '-inf';

    return (
      <div className="flex-1 w-full flex flex-col items-center">
        <div 
            ref={faderRef} 
            className="w-12 h-full bg-[#121212] rounded-full relative cursor-ns-resize pt-4 pb-4"
            onMouseDown={handleMouseDown}
        >
          <div className="w-1 h-full bg-[#0A0A0A] mx-auto rounded-full relative">
            <div 
              className="absolute w-10 h-14 bg-gradient-to-b from-[#444] to-[#222] rounded shadow-lg border border-[#555] left-1/2 -translate-x-1/2 flex items-center justify-center"
              style={{ bottom: `calc(${value * 100}% - 28px)` }}
            >
              <div className="w-8 h-[2px] bg-black/50" />
            </div>
          </div>
        </div>
        <div className="mt-2 text-center bg-[#121212] px-2 py-0.5 rounded">
            <span className="text-xs font-mono text-gray-400">{displayDb} dB</span>
        </div>
      </div>
    );
};


