import React, { useState } from 'react';
import Layout from './components/Layout';
import StemSplitter from './components/StemSplitter';
import Mixer from './components/Mixer';
import Mastering from './components/Mastering';
import SystemCore from './components/SystemCore';
import { View } from './types';
import { Mic, Music } from 'lucide-react';

// Placeholder components for views not fully implemented in this iteration
const PlaceholderView: React.FC<{ title: string; icon: any; desc: string }> = ({ title, icon: Icon, desc }) => (
  <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-50">
    <Icon size={64} className="text-[#333] mb-6" />
    <h2 className="text-2xl font-bold text-[#666] mb-2">{title}</h2>
    <p className="text-[#444] max-w-md">{desc}</p>
  </div>
);

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>(View.MIXER);

  const renderView = () => {
    switch (currentView) {
      case View.STEM_SPLITTER:
        return <StemSplitter />;
      case View.MIXER:
        return <Mixer />;
      case View.MASTERING:
        return <Mastering />;
      case View.SYSTEM_CORE:
        return <SystemCore />;
      case View.AURA:
        return <PlaceholderView title="AURA VOICE MORPH" icon={Mic} desc="RVC (Retrieval-based Voice Conversion) module interface. Allows loading .pth weights and indexing for voice replacement." />;
      case View.DRUM_TRIGGER:
        return <PlaceholderView title="DRUM TRIGGER" icon={Music} desc="Audio-to-MIDI conversion logic for drum replacement. Detects transients and maps them to standard General MIDI notes." />;
      default:
        return <Mixer />;
    }
  };

  return (
    <Layout currentView={currentView} setView={setCurrentView}>
      {renderView()}
    </Layout>
  );
};

export default App;

