    <content><![CDATA[import React, { useState, useRef, useEffect } from 'react';
import { Track } from '../types';
import Knob from './Knob';
import { Power, Music, Waves, GitCommit, Sparkles } from 'lucide-react';

interface ChannelStripProps {
