const ExportMenu: React.FC = () => {
    const [isOpen, setIsOpen] = useState(false);
    const menuRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener("mousedown", handleClickOutside);
        return () => document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    const handleExport = (type: 'mix' | 'wav' | 'midi' | 'loop') => {
        let content = '';
        let filename = '';

        const header = `STRANGELET LAB EXPORT\nTIMESTAMP: ${new Date().toISOString()}\n\n`;

        switch (type) {
            case 'mix':
                content = header + "This is a placeholder for your custom mix WAV file.\nMix settings would be included here.";
                filename = 'custom_mix_export.txt';
                break;
            case 'wav':
                content = header + "This is a placeholder for your WAV stems ZIP file.\nIncludes: Vocals.wav, Drums.wav, Bass.wav, Synth.wav";
                filename = 'wav_stems_export.txt';
                break;
            case 'midi':
                content = header + "This is a placeholder for your MIDI stems ZIP file.\nIncludes: Vocals.mid, Drums.mid, Bass.mid, Synth.mid";
                filename = 'midi_stems_export.txt';
                break;
            case 'loop':
                content = header + "This is a placeholder for your exported loop selection WAV file.";
                filename = 'loop_selection_export.txt';
                break;
        }

        const blob = new Blob([content], { type: 'text/plain' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        setIsOpen(false);
    };

    const menuItems = [
        { label: "Custom Mix (.wav)", type: 'mix' as const },
        { label: "WAV Stems (.zip)", type: 'wav' as const },
        { label: "MIDI Stems (.zip)", type: 'midi' as const },
        { label: "Loop Selection (.wav)", type: 'loop' as const }
    ];

    return (
        <div className="relative" ref={menuRef}>
            <button
                onClick={() => setIsOpen(!isOpen)}
                className="flex items-center gap-2 px-4 py-2 bg-[#1E1E1E] border border-[#333] rounded-md hover:border-[#FFD700] transition-colors"
            >
                <Download size={16} className="text-[#FFD700]" />
                <span className="text-sm font-medium text-white">Export</span>
                <ChevronDown size={16} className={`text-[#666] transition-transform ${isOpen ? 'rotate-180' : ''}`} />
            </button>
            {isOpen && (
                <div className="absolute right-0 mt-2 w-56 bg-[#1E1E1E] border border-[#333] rounded-md shadow-lg z-20">
                    <div className="p-1">
                        {menuItems.map(item => (
                             <button 
                                key={item.label} 
                                onClick={() => handleExport(item.type)}
                                className="w-full text-left block px-3 py-2 text-sm text-[#A0A0A0] hover:bg-[#252525] hover:text-[#FFD700] rounded-md"
                             >
                                {item.label}
                             </button>
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
};


