        setIsPlaying(false);
        setPlayheadPosition(0);
        Object.values(trackNodesRef.current).forEach(nodes => {
            try { nodes.panner.disconnect(masterGain); } catch(e) {}
        });
        break;
      case 'rewind':
        setPlayheadPosition(0);
        break;
      case 'loop':
        setLoopEnabled(prev => !prev);
        break;
    }
  };

  return (
